	//  /(............................/7
	scanf("%lld%lld",&n,&q);
	for(int i=1;i<=n;i++){
		cin>>ss1[i]>>ss2[i];
	}
	for(int i=1;i<=q;i++){
		cin>>tt1>>tt2;
		cnt=0;
		for(int k=1;k<=n;k++){
			string s=tt1;
			bool b=0,c=0;
			for(int j=0;j<s.size();j++){
				if(s[j]==ss1[k][0]){
					for(int x=0;x<ss1[k].size();x++){
						if(s[j+x]!=ss1[k][x]){
							b=1;
							break;
						}
					}
					if(b==0){
						for(int x=0;x<ss2[k].size();x++){
							s[j+x]=ss2[k][x];
						}
						c=1;
						break;
					}
				}
			}
			if(c==1 && s==tt2) cnt++; 
		}
		printf("%lld/n",cnt);
	}
	return 0;
